 {incoming&&<IncomingShare key={incoming.id} capture={incoming} categories={readingCategories(storedState.resources)} timezone={storedState.settings.timezone} onRead={(text,title,space,choice)=>{if(updateAll(s=>saveSharedReading(s,{id:incoming.id,text,title,workspace:space,category:choice.category,asap:choice.asap}))){setIncoming(null);setWorkspace(space);go('library');notify(choice.asap?'Saved. Read it by the end of this week.':'Saved to read'+(choice.category?' in '+choice.category:'')+'.');return true;}return false;}} onDiscard={()=>{nativeBridge()?.acknowledgeShare?.(incoming.id);setIncoming(null);}} onClose={()=>setIncoming(null)} onSave={(text,space)=>{if(updateAll(s=>captureInbox(s,text,space,'shared',incoming.id))){setIncoming(null);setWorkspace(space);go('inbox');notify('Saved to your inbox.');return true;}return false;}}/>}
